class Tank(AttackUnit):
    siege_developed = False  # 클래스 변수

    def __init__(self):
        AttackUnit.__init__(self, "탱크", 150, 35, 1)
        self.siege_mode = False  # 인스턴스 변수

    def set_siege_mode(self):  # 시지 모드 토글
