Python<pre><code>from mysql.connector import connect, Error

# 연결 함수
def connect_db():
    return connect(
        host="localhost",
        user="root",
        password="비밀번호",
        database="pyuserdb"
    )

# 1. 회원 등록
def insert_user():
    try:
        conn = connect_db()
        with conn.cursor() as cursor:
            print("\n[회원 등록]")
            name = input("이름: ")
            email = input("이메일: ")
            age = int(input("나이: "))

            sql = "INSERT INTO users (name, email, age) VALUES (%s, %s, %s)"
            cursor.execute(sql, (name, email, age))
            conn.commit()
            print("✅ 등록 완료!")
    except Error as e:
        print("❌ 오류:", e)
    finally:
        if conn.is_connected():
            conn.close()

# 2. 전체 회원 조회
def show_all_users():
    try:
        conn = connect_db()
        with conn.cursor() as cursor:
            cursor.execute("SELECT * FROM users ORDER BY id")
            rows = cursor.fetchall()
            print("\n[전체 회원 목록]")
            if rows:
                print(f"{'ID':&lt;5} {'이름':&lt;10} {'이메일':&lt;25} {'나이':&lt;5} {'가입일'}")
                print("-" * 60)
                for row in rows:
                    id, name, email, age, created_at = row
                    print(f"{id:&lt;5} {name:&lt;10} {email:&lt;25} {age:&lt;5} {created_at}")
            else:
                print("등록된 회원이 없습니다.")
    except Error as e:
        print("❌ 오류:", e)
    finally:
        if conn.is_connected():
            conn.close()

# 3. 회원 검색
def find_user():
    try:
        conn = connect_db()
        with conn.cursor() as cursor:
            print("\n[회원 검색]")
            keyword = input("이름 또는 ID 입력: ")
            if keyword.isdigit():
                cursor.execute("SELECT * FROM users WHERE id = %s", (int(keyword),))
            else:
                cursor.execute("SELECT * FROM users WHERE name LIKE %s", (f"%{keyword}%",))
            rows = cursor.fetchall()
            if rows:
                print(f"{'ID':&lt;5} {'이름':&lt;10} {'이메일':&lt;25} {'나이':&lt;5} {'가입일'}")
                print("-" * 60)
                for row in rows:
                    id, name, email, age, created_at = row
                    print(f"{id:&lt;5} {name:&lt;10} {email:&lt;25} {age:&lt;5} {created_at}")
            else:
                print("해당 회원 없음.")
    except Error as e:
        print("❌ 오류:", e)
    finally:
        if conn.is_connected():
            conn.close()

# 4. 회원 수정
def update_user():
    try:
        conn = connect_db()
        with conn.cursor() as cursor:
            print("\n[회원 수정]")
            user_id = input("ID 입력: ")
            cursor.execute("SELECT * FROM users WHERE id = %s", (user_id,))
            if not cursor.fetchone():
                print("해당 회원 없음.")
                return
            print("1. 이메일 수정  2. 나이 수정")
            choice = input("선택 &gt; ")
            if choice == "1":
                new_email = input("새 이메일 입력: ")
                cursor.execute("UPDATE users SET email = %s WHERE id = %s", (new_email, user_id))
            elif choice == "2":
                new_age = int(input("새 나이 입력: "))
                cursor.execute("UPDATE users SET age = %s WHERE id = %s", (new_age, user_id))
            else:
                print("잘못된 선택입니다.")
                return
            conn.commit()
            print("✅ 수정 완료!")
    except Error as e:
        print("❌ 오류:", e)
    finally:
        if conn.is_connected():
            conn.close()

# 5. 회원 삭제
def delete_user():
    try:
        conn = connect_db()
        with conn.cursor() as cursor:
            print("\n[회원 삭제]")
            user_id = input("삭제할 ID 입력: ")
            cursor.execute("SELECT * FROM users WHERE id = %s", (user_id,))
            user = cursor.fetchone()
            if not user:
                print("회원 없음.")
                return
            confirm = input(f"{user[1]}님을 삭제하시겠습니까? (y/n): ")
            if confirm.lower() != "y":
                print("삭제 취소.")
                return
            cursor.execute("DELETE FROM users WHERE id = %s", (user_id,))
            conn.commit()
            print("🗑️ 삭제 완료!")
    except Error as e:
        print("❌ 오류:", e)
    finally:
        if conn.is_connected():
            conn.close()

# 메인 메뉴
